class Solution {
public:
    string splitLoopedString(vector<string>& strs) {
        string combined;
        for (string& s : strs) {
            string reversed = s;
            reverse(reversed.begin(), reversed.end());
            s = max(s, reversed);
            combined += s;
        }
        string best;
        int offset = 0;
        for (const string& original : strs) {
            string middle = combined.substr(offset + original.size())
                          + combined.substr(0, offset);
            for (int orientation = 0; orientation < 2; ++orientation) {
                string s = original;
                if (orientation == 1) {
                    reverse(s.begin(), s.end());
                }
                for (int cut = 0; cut < static_cast<int>(s.size()); ++cut) {
                    string candidate = s.substr(cut) + middle + s.substr(0, cut);
                    best = max(best, candidate);
                }
            }
            offset += original.size();
        }
        return best;
    }
};
